def get_data(request):
    data = request.json
    db = firestore.Client()
    collection = db.collection('users')
    doc_ref = collection.document(data['user_id'])
    doc = doc_ref.get()

    user = doc.to_dict()
    if not user:
        return 'User not found', 404

    return jsonify(user)

